import type { Chart, Plugin } from 'chart.js';

import {
  POS_BAR_EDGE_INSET_FROM_BLEED_PX,
  POS_BAR_INNER_GAP_PX,
  POS_BAR_WIDTH_PX,
  POS_BLEED_LINE_MARGIN_PX,
} from '../constants';

function getGroupedBarWidthPx(numDatasets: number): number {
  return (
    numDatasets * POS_BAR_WIDTH_PX + (numDatasets - 1) * POS_BAR_INNER_GAP_PX
  );
}

function getPosGroupCenterXs(chart: Chart<'bar'>): number[] {
  const numGroups = chart.data.labels?.length ?? 0;
  if (numGroups === 0 || chart.width <= 0) {
    return [];
  }

  const totalGroupWidth = getGroupedBarWidthPx(chart.data.datasets.length);
  const plotLeft = POS_BLEED_LINE_MARGIN_PX + POS_BAR_EDGE_INSET_FROM_BLEED_PX;
  const plotRight =
    chart.width - POS_BLEED_LINE_MARGIN_PX - POS_BAR_EDGE_INSET_FROM_BLEED_PX;

  const firstCenter = plotLeft + totalGroupWidth / 2;
  const lastCenter = plotRight - totalGroupWidth / 2;

  if (numGroups === 1) {
    return [(firstCenter + lastCenter) / 2];
  }

  const step = (lastCenter - firstCenter) / (numGroups - 1);
  return Array.from(
    { length: numGroups },
    (_, index) => firstCenter + index * step,
  );
}

function positionGroupedBars(
  chart: Chart<'bar'>,
  groupCenters: number[],
): void {
  const numDatasets = chart.data.datasets.length;
  const totalGroupWidth = getGroupedBarWidthPx(numDatasets);

  for (let datasetIndex = 0; datasetIndex < numDatasets; datasetIndex++) {
    const meta = chart.getDatasetMeta(datasetIndex);
    const datasetOffset =
      datasetIndex * (POS_BAR_WIDTH_PX + POS_BAR_INNER_GAP_PX) -
      totalGroupWidth / 2 +
      POS_BAR_WIDTH_PX / 2;

    meta.data.forEach((element, groupIndex) => {
      const center = groupCenters[groupIndex];
      if (!Number.isFinite(center)) {
        return;
      }

      const barGeom = element as unknown as { x: number; width: number };
      barGeom.x = center + datasetOffset;
      barGeom.width = POS_BAR_WIDTH_PX;
    });
  }
}

export function createPosBarSpacingPlugin(
  getShell: () => HTMLDivElement | null,
): Plugin<'bar'> {
  return {
    id: 'posBarSpacing',
    afterUpdate(chart) {
      const groupCenters = getPosGroupCenterXs(chart);
      if (groupCenters.length === 0) {
        return;
      }

      const scaleX = chart.scales.x as Chart<'bar'>['scales']['x'] & {
        __posOriginalGetPixelForValue?: (value: number | string) => number;
      };

      if (!scaleX.__posOriginalGetPixelForValue) {
        scaleX.__posOriginalGetPixelForValue =
          scaleX.getPixelForValue.bind(scaleX);
      }

      const originalGetPixelForValue = scaleX.__posOriginalGetPixelForValue;
      scaleX.getPixelForValue = (value: number | string) => {
        const index = typeof value === 'number' ? value : Number(value);
        if (
          Number.isInteger(index) &&
          index >= 0 &&
          index < groupCenters.length
        ) {
          return groupCenters[index];
        }
        return originalGetPixelForValue(value);
      };
    },
    beforeDatasetsDraw(chart) {
      const shell = getShell();
      if (!shell?.isConnected || chart.width <= 0) {
        return;
      }

      const groupCenters = getPosGroupCenterXs(chart);
      if (groupCenters.length === 0) {
        return;
      }

      positionGroupedBars(chart, groupCenters);
    },
  };
}
